import json
import asyncio
from typing import Any
import httpx
from fastmcp import Server, Tool


def create_openapi_mcp_server(
    openapi_spec: dict,
    http_client: httpx.AsyncClient
) -> Server:
    """Create an MCP server from an OpenAPI specification."""

    server = Server("openapi-mcp")

    # Parse OpenAPI spec and create tools
    for path, methods in openapi_spec.get("paths", {}).items():
        for method, operation in methods.items():
            if method not in ["get", "post", "put", "delete", "patch"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path}")
            summary = operation.get("summary", "")

            # Collect parameters
            params = operation.get("parameters", [])
            request_body = operation.get("requestBody", {})

            # Build input schema
            input_schema = {
                "type": "object",
                "properties": {},
                "required": []
            }

            # Add query/path parameters
            for param in params:
                param_name = param["name"]
                param_schema = param.get("schema", {"type": "string"})
                input_schema["properties"][param_name] = param_schema
                if param.get("required"):
                    input_schema["required"].append(param_name)

            # Add request body
            if request_body:
                body_schema = (
                    request_body
                    .get("content", {})
                    .get("application/json", {})
                    .get("schema", {})
                )
                if body_schema:
                    input_schema["properties"]["body"] = body_schema
                    if request_body.get("required"):
                        input_schema["required"].append("body")

            # Create handler with proper closure
            def make_handler(
                http_method: str,
                api_path: str,
                param_list: list,
                has_body: bool
            ):
                async def handler(**kwargs: Any) -> dict:
                    path = api_path
                    query_params = {}

                    for param in param_list:
                        param_name = param["name"]
                        if param_name in kwargs:
                            if param["in"] == "path":
                                path = path.replace(
                                    f"{{{param_name}}}", 
                                    str(kwargs[param_name])
                                )
                            elif param["in"] == "query":
                                query_params[param_name] = kwargs[param_name]

                    request_kwargs = {}
                    if query_params:
                        request_kwargs["params"] = query_params
                    if has_body and "body" in kwargs:
                        request_kwargs["json"] = kwargs["body"]

                    try:
                        response = await http_client.request(
                            http_method.upper(),
                            path,
                            **request_kwargs
                        )
                        response.raise_for_status()
                        try:
                            return {
                                "status": response.status_code,
                                "data": response.json()
                            }
                        except json.JSONDecodeError:
                            return {
                                "status": response.status_code,
                                "data": response.text
                            }
                    except httpx.HTTPError as e:
                        return {"status": "error", "message": str(e)}

                return handler

            handler = make_handler(method, path, params, bool(request_body))

            tool = Tool(
                name=operation_id,
                description=summary or f"{method.upper()} {path}",
                inputSchema=input_schema,
                handler=handler
            )
            server.add_tool(tool)

    return server


async def main():
    # Example OpenAPI spec
    openapi_spec = {
        "openapi": "3.0.0",
        "info": {"title": "Sample API", "version": "1.0.0"},
        "paths": {
            "/users": {
                "get": {
                    "operationId": "listUsers",
                    "summary": "List all users",
                    "parameters": [
                        {
                            "name": "limit",
                            "in": "query",
                            "schema": {"type": "integer"}
                        }
                    ]
                },
                "post": {
                    "operationId": "createUser",
                    "summary": "Create a new user",
                    "requestBody": {
                        "required": True,
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "object",
                                    "properties": {
                                        "name": {"type": "string"},
                                        "email": {"type": "string"}
                                    }
                                }
                            }
                        }
                    }
                }
            },
            "/users/{userId}": {
                "get": {
                    "operationId": "getUser",
                    "summary": "Get user by ID",
                    "parameters": [
                        {
                            "name": "userId",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "string"}
                        }
                    ]
                }
            }
        }
    }

    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = create_openapi_mcp_server(openapi_spec, client)
        async with server:
            await asyncio.Event().wait()


if __name__ == "__main__":
    asyncio.run(main())

